import fs from 'node:fs';import ts from '../extension/node_modules/typescript/lib/typescript.js';
const source=fs.readFileSync('docs/mapping/raw/studio.js','utf8'),file=ts.createSourceFile('studio.js',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS),classes=[];
function visit(n){if(ts.isClassExpression(n)||ts.isClassDeclaration(n)){const text=n.getText(file),registration=text.match(/\.register\([^,]+,"([^"]+)"\)/);classes.push({symbol:n.name?.getText(file)||(ts.isVariableDeclaration(n.parent)?n.parent.name.getText(file):null),component:registration?.[1]||null,start:n.getStart(file),end:n.end,extends:n.heritageClauses?.map(h=>h.getText(file)),members:n.members.map(m=>({name:m.name?.getText(file)||'constructor',kind:ts.SyntaxKind[m.kind],static:!!m.modifiers?.some(m=>m.kind===ts.SyntaxKind.StaticKeyword)}))});}ts.forEachChild(n,visit);}visit(file);
const urls=[...new Set(source.match(/https?:\/\/[^\s"'`<>\\)]+/g)||[])].sort();
const terms=['indexedDB.open','createObjectStore','localStorage','sessionStorage','navigator.storage','showDirectoryPicker','showOpenFilePicker','showSaveFilePicker','getDirectory','createWritable','postMessage','new Worker','VideoEncoder','VideoDecoder','AudioEncoder','AudioDecoder','OffscreenCanvas','WebGL','JSON.parse','JSON.stringify','history.undo','undo()','redo()','toJSON','fromJSON','window.','globalThis.'];
const occurrences=Object.fromEntries(terms.map(term=>{const found=[];let at=-1;while((at=source.indexOf(term,at+1))>=0)found.push({offset:at,excerpt:source.slice(Math.max(0,at-120),at+220)});return [term,found]}));
fs.writeFileSync('docs/mapping/bundle-index.json',JSON.stringify({version:'1.7.12',classes,urls,occurrences},null,2));
console.log(JSON.stringify({classes:classes.length,registered:classes.filter(c=>c.component).length,components:classes.filter(c=>c.component).map(c=>c.component),interesting:classes.filter(c=>c.component==='ProjectApp'||c.members.some(m=>['toJSON','fromJSON','undo','redo','serialize'].includes(m.name))).map(c=>({symbol:c.symbol,component:c.component,members:c.members.map(m=>m.name)})),occurrenceCounts:Object.fromEntries(Object.entries(occurrences).map(([k,v])=>[k,v.length]))},null,2));

